fn fixture(name: &str) -> &'static Fixture {
    FIXTURES
        .iter()
        .find(|fixture| fixture.0 == name)
        .unwrap_or_else(|| panic!("missing fixture {name}"))
}

fn assert_matches(name: &str, actual: &[Option<f64>]) {
    let (_, head, tail) = fixture(name);
    assert_eq!(actual.len(), CLOSE.len(), "{name}: row count");
    let rows = head.iter().enumerate().chain(
        tail.iter()
            .enumerate()
            .map(|(offset, value)| (actual.len() - tail.len() + offset, value)),
    );
    for (row, &expected) in rows {
        match actual[row] {
            None => assert!(
                expected.is_nan(),
                "{name} row {row}: missing, expected {expected}"
            ),
            Some(value) => {
                assert!(
                    !expected.is_nan(),
                    "{name} row {row}: {value} during warm-up"
                );
                assert!(
                    (value - expected).abs() <= 1e-9 * expected.abs().max(1.0),
                    "{name} row {row}: {value} != {expected}"
                );
            }
        }
    }
}

fn input(rows: usize) -> IndicatorInput<'static> {
    IndicatorInput {
        times: &TIMES[..rows],
        open: &OPEN[..rows],
        high: &HIGH[..rows],
        low: &LOW[..rows],
        close: &CLOSE[..rows],
        volume: &VOLUME[..rows],
        amount: &[],
    }
}

static TIMES: [i64; 150] = {
    let mut times = [0; 150];
    let mut row = 0;
    while row < 150 {
        times[row] = 1_700_006_400 + row as i64 * 86_400;
        row += 1;
    }
    times
};

/// Full-rebuild outputs of a runtime, after checking that bar-by-bar streaming agrees.
fn runtime(make: impl Fn() -> IncrementalState) -> Vec<Vec<Option<f64>>> {
    let rows = CLOSE.len();
    let expand = |state: &IncrementalState| {
        (0..state.output_count())
            .map(|output| {
                let mut values = vec![None; state.output_from(output)];
                values.extend(
                    state
                        .output(output)
                        .iter()
                        .map(|&value| (!value.is_nan()).then_some(value)),
                );
                values
            })
            .collect::<Vec<_>>()
    };
    let mut full = make();
    full.rebuild_from(input(rows), 0);
    let full = expand(&full);

    let mut streaming = make();
    let mut streamed: Vec<Vec<Option<f64>>> = Vec::new();
    for len in 1..=rows {
        streaming.rebuild_from(input(len), len - 1);
        streamed.resize(streaming.output_count(), Vec::new());
        for (output, values) in streamed.iter_mut().enumerate() {
            let from = streaming.output_from(output);
            values.truncate(from);
            values.resize(from, None);
            values.extend(
                streaming
                    .output(output)
                    .iter()
                    .map(|&value| (!value.is_nan()).then_some(value)),
            );
        }
    }
    for (output, (full, streamed)) in full.iter().zip(&streamed).enumerate() {
        for (row, (full, streamed)) in full.iter().zip(streamed).enumerate() {
            match (full, streamed) {
                (Some(full), Some(streamed)) => {
                    assert!((full - streamed).abs() < 1e-9, "output {output} row {row}")
                }
                (None, None) => {}
                _ => panic!("output {output} row {row}: {full:?} != {streamed:?}"),
            }
        }
    }
    full
}

#[test]
fn tradingview_conventions_match_the_pine_reference_definitions() {
    assert_matches("tradingview ta.ema(close, 20)", &ema(&CLOSE, 20));
    assert_matches(
        "tradingview ta.ema(close, 20)",
        &runtime(|| IncrementalState::ema(20))[0],
    );

    let points = macd(&CLOSE, 12, 26, 9);
    let runtime_macd = runtime(|| IncrementalState::macd(12, 26, 9));
    for (index, name) in ["line", "signal", "hist"].into_iter().enumerate() {
        let name = format!("tradingview ta.macd(close, 12, 26, 9) {name}");
        let dense = points
            .iter()
            .map(|point| [point.macd, point.signal, point.histogram][index])
            .collect::<Vec<_>>();
        assert_matches(&name, &dense);
        assert_matches(&name, &runtime_macd[index]);
    }

    assert_matches("tradingview ta.rsi(close, 14)", &rsi(&CLOSE, 14));
    assert_matches(
        "tradingview ta.rsi(close, 14)",
        &runtime(|| IncrementalState::rsi(14))[0],
    );

    let bands = bollinger(&CLOSE, 20, 2.0);
    let runtime_bands = runtime(|| IncrementalState::bollinger(20, 2.0));
    for (index, name) in ["upper", "basis", "lower"].into_iter().enumerate() {
        let name = format!("tradingview ta.bb(close, 20, 2) {name}");
        let dense = bands
            .iter()
            .map(|point| [point.upper, point.middle, point.lower][index])
            .collect::<Vec<_>>();
        assert_matches(&name, &dense);
        assert_matches(&name, &runtime_bands[index]);
    }

    let stochastic_points = stochastic(&HIGH, &LOW, &CLOSE, 14, 3);
    let runtime_stochastic = runtime(|| IncrementalState::stochastic(14, 3));
    for (index, name) in ["%K", "%D"].into_iter().enumerate() {
        let name = format!("tradingview Stochastic(14, 1, 3) {name}");
        let dense = stochastic_points
            .iter()
            .map(|point| [point.k, point.d][index])
            .collect::<Vec<_>>();
        assert_matches(&name, &dense);
        assert_matches(&name, &runtime_stochastic[index]);
    }
}

#[test]
fn china_conventions_match_the_tdx_formula_definitions() {
    let china = IndicatorConvention::China;
    assert_eq!(china.seed(), IndicatorSeed::FirstValue);
    assert_eq!(china.macd_histogram_multiplier(), 2.0);
    assert_eq!(china.deviation_estimator(), DeviationEstimator::Sample);
    let seed = china.seed();

    assert_matches("tdx EMA(CLOSE,20)", &ema_with_seed(&CLOSE, 20, seed));
    assert_matches(
        "tdx EMA(CLOSE,20)",
        &runtime(|| IncrementalState::ema_with_seed(20, seed))[0],
    );

    let points = macd_with(&CLOSE, 12, 26, 9, seed, china.macd_histogram_multiplier());
    let runtime_macd =
        runtime(|| IncrementalState::macd_with(12, 26, 9, seed, china.macd_histogram_multiplier()));
    for (index, name) in ["DIF", "DEA", "MACD"].into_iter().enumerate() {
        let name = format!("tdx MACD(12,26,9) {name}");
        let dense = points
            .iter()
            .map(|point| [point.macd, point.signal, point.histogram][index])
            .collect::<Vec<_>>();
        assert_matches(&name, &dense);
        assert_matches(&name, &runtime_macd[index]);
    }

    for period in [6, 12, 24] {
        let name = format!("tdx RSI{period}");
        assert_matches(&name, &rsi_with_seed(&CLOSE, period, seed));
        assert_matches(
            &name,
            &runtime(|| IncrementalState::rsi_with_seed(period, seed))[0],
        );
    }

    let estimator = china.deviation_estimator();
    let bands = bollinger_with(&CLOSE, 20, 2.0, estimator);
    let runtime_bands = runtime(|| IncrementalState::bollinger_with(20, 2.0, estimator));
    for (index, name) in ["UB", "BOLL", "LB"].into_iter().enumerate() {
        let name = format!("tdx BOLL(20,2) {name}");
        let dense = bands
            .iter()
            .map(|point| [point.upper, point.middle, point.lower][index])
            .collect::<Vec<_>>();
        assert_matches(&name, &dense);
        assert_matches(&name, &runtime_bands[index]);
    }

    let kdj_points = kdj(&HIGH, &LOW, &CLOSE, 9, 3, 3);
    let runtime_kdj = runtime(|| IncrementalState::kdj(9, 3, 3));
    for (index, name) in ["K", "D", "J"].into_iter().enumerate() {
        let name = format!("textbook KDJ(9,3,3) {name}");
        let dense = kdj_points
            .iter()
            .map(|point| [point.k, point.d, point.j][index])
            .collect::<Vec<_>>();
        assert_matches(&name, &dense);
        assert_matches(&name, &runtime_kdj[index]);
    }
}
